def print_table():
    import sys

    records = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        records.append(line.split())

    if not records:
        return

    # Determine the number of columns
    max_cols = max(len(row) for row in records)
    max_widths = [0] * max_cols

    # Determine the max width for each column
    for row in records:
        for i, field in enumerate(row):
            max_widths[i] = max(max_widths[i], len(field))

    # Print the table
    for row in records:
        for i, field in enumerate(row):
            print(field.ljust(max_widths[i]), end='')
            if i < max_cols - 1:
                print(' ', end='')
        print()

