from phonenumbers import PhoneNumberFormat, NumberFormat

def validate_and_format_phone_number(input_number, country_code):
    # Parse the number with the provided country code
    try:
        parsed_number = phonenumbers.parse(input_number, country_code)
        if phonenumbers.is_valid_number(parsed_number):
            # Format the number in international format (E.164)
            formatted_number = phonenumbers.format_number(
                parsed_number,
                PhoneNumberFormat.INTernational
            )
            return formatted_number
        else:
            return "Invalid number for this country code"
    except phonenumbers.NumberParseException as e:
        return f"Invalid or unrecognized phone number: {e}"

