import time
from functools import wraps

cache = {}

def cache_with_ttl(ttl_seconds):
    def decorator(func):
        func_key = func.__name__
        func_cache = cache.get(func_key, {})

        @wraps(func)
        def wrapper(*args, **kwargs):
            # Generate a hashable key for the function call
            key = (args, frozenset(sorted(kwargs.items())))
            current_time = time.time()

            if key in func_cache:
                result, expire_time = func_cache[key]
                if current_time < expire_time:
                    return result

            # Compute the result and store it
            result = func(*args, **kwargs)
            expire_time = current_time + ttl_seconds
            func_cache[key] = (result, expire_time)

            return result

        return wrapper

    return decorator

