def print_aligned_table(data, headers):
    # Calculate maximum widths for each column
    max_widths = []
    for col in range(len(headers)):
        header = headers[col]
        max_len = len(header)
        for row in data:
            value = row[header]
            current_len = len(str(value))
            if current_len > max_len:
                max_len = current_len
        max_widths.append(max_len)

    # Print headers
    for i, header in enumerate(headers):
        print(f"{header:<{max_widths[i]}}", end='')
    print()

    # Print data rows
    for row in data:
        for i, header in enumerate(headers):
            value = row[header]
            print(f"{value:<{max_widths[i]}}", end='')
        print()

