def find_closest_match(query, names):
    """
    Find the name in the list that is closest to the query string.

    Args:
        query (str): The query string to match against.
        names (list[str]): A list of names to search through.

    Returns:
        str: The name from the list that is closest to the query.
    """

    def levenshtein(s1, s2):
        """
        Calculate the Levenshtein distance between two strings.
        """
        if len(s1) < len(s2):
            return levenshtein(s2, s1)
        if not s1:
            return len(s2)
        if not s2:
            return len(s1)

        # Create a matrix to store distances
        matrix = [[0] * (len(s2) + 1) for _ in range(len(s1) + 1)]

        # Initialize the first row and column
        for i in range(len(s1) + 1):
            matrix[i][0] = i
        for j in range(len(s2) + 1):
            matrix[0][j] = j

        # Fill the matrix
        for i in range(1, len(s1) + 1):
            for j in range(1, len(s2) + 1):
                if s1[i - 1] == s2[j - 1]:
                    cost = 0
                else:
                    cost = 1
                matrix[i][j] = min(
                    matrix[i - 1][j] + 1,    # Deletion
                    matrix[i][j - 1] + 1,    # Insertion
                    matrix[i - 1][j - 1] + cost  # Substitution
                )

        return matrix[len(s1)][len(s2)]

    min_distance = float('inf')
    closest_name = None

    for name in names:
        distance = levenshtein(query, name)
        if distance < min_distance:
            min_distance = distance
            closest_name = name

    return closest_name

import time
import functools

def cache_with_ttl(ttl_seconds):
    """
    A decorator that caches the result of a function with a time-to-live (TTL).

    Parameters:
        - ttl_seconds (int): The duration (in seconds) for which the result is cached.

    Usage:
        @cache_with_ttl(10)
        def expensive_function(...):
            ...
    """
    def decorator(func):
        cache = {}

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Convert positional and keyword arguments to hashable types
            args_tuple = tuple(args)
            sorted_kwargs = sorted(kwargs.items())
            key = (args_tuple, sorted_kwargs)

            # Check the cache
            if key in cache:
                stored_time = cache[key][1]
                if time.time() - stored_time > ttl_seconds:
                    # Evict the entry if expired
                    del cache[key]

            # Compute or retrieve the result
            if key not in cache:
                result = func(*args, **kwargs)
                cache[key] = (result, time.time())

            return cache[key][0]

        return wrapper

    return decorator

