import redis

r = redis.Redis(host='localhost', port=6379, db=0)

def cache_with_ttl_redis(ttl, key_prefix='cache:'):
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Generate key
            key = f"{key_prefix}{func.__name__}:{args}:{kwargs}"
            if r.ttl(key) < 0:
                result = func(*args, **kwargs)
                r.setex(key, ttl, result)
            else:
                result = r.get(key)
            return result
        return wrapper
    return decorator

