import time
from functools import wraps

def cache_with_ttl(maxsize=100, ttl=300):
    cache = {}

    def decorator(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, frozenset(kwargs.items()))

            if key in cache:
                expire_time, result = cache[key]
                if time.time() - expire_time < ttl:
                    return result

            # Compute the result
            result = func(*args, **kwargs)
            # Store the result with its expiration time
            cache[key] = (time.time(), result)
            return result
        return wrapper
    return decorator

