def get_env_value(key, default):
    try:
        with open('.env') as f:
            lines = f.readlines()
    except FileNotFoundError:
        return default

    env_dict = {}

    for line in lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' in line:
            k, v = line.split('=', 1)
            env_dict[k.strip()] = v.strip()

    return env_dict.get(key, default)
